if hasattr(filing, 'skip_status_listener') and filing.skip_status_listener:
        return
    # changes are part of the class and are not externalized
    if filing.filing_type == 'lear_epoch':
        filing._status = Filing.Status.EPOCH.value  # pylint: disable=protected-access
    elif filing.transaction_id:
        filing._status = Filing.Status.COMPLETED.value  # pylint: disable=protected-access
    elif filing.payment_completion_date or filing.source == Filing.Source.COLIN.value:
        filing._status = Filing.Status.PAID.value  # pylint: disable=protected-access
    elif filing.payment_token:
        filing._status = Filing.Status.PENDING.value  # pylint: disable=protected-access
    else:
        filing._status = Filing.Status.DRAFT.value  # pylint: disable=protected-access

business.state = Business.State.ACTIVE

    if nr_number := business_info_obj.get('nrNumber', None):
        filing_meta.registration = {**filing_meta.registration,
                                    **{'nrNumber': nr_number,
                                       'legalName': business_info_obj.get('legalName', None)}}

    if not business:
        # raise QueueException(f'Registration {filing_rec.id}, Unable to create business.')
        raise Exception(f'Registration {filing_rec.id}, Unable to create business.')

    if offices := registration_filing['offices']:
        update_offices(business, offices)

    if parties := registration_filing.get('parties'):
        update_parties(business, parties, filing_rec)

    # update court order, if any is present

@staticmethod
    def get_filings_by_status(business_id: int, status: list, after_date: date = None):
        """Return the filings with statuses in the status array input."""
        storages = FilingStorage.get_filings_by_status(business_id, status, after_date)
        filings = []
        for storage in storages:
            filing = Filing()
            filing.storage = storage
            filings.append(filing)

        return filings

worker_processes auto;

events {
  worker_connections 512;
}

http {
  server {
    listen 80;

    location /bcol-api {
      rewrite ^/bcol-api/(.*) /$1 break;
      proxy_pass http://bcol:4010/;
    }

    location /pay-api {
      	rewrite ^/pay-api/(.*) /$1 break;
      	proxy_set_header  Prefer example=/$1;
      	proxy_pass http://pay:4010/;
    }


    location /reports-api {
	  	set $last_path_component example1;
      	rewrite ^/reports-api/api/v1/(.*) /$1 break;
	 	proxy_set_header  Prefer example=$last_path_component;
		proxy_set_header  Accept "application/json";
      	proxy_pass http://reports:4010/;
    }
